// fayl: lib/format-price.ts
export function formatPrice(amount: number): string {
  const digits = Math.round(amount).toString()
  // har uch raqamdan keyin bo'sh joy: 1234567 → 1 234 567
  return digits.replace(/\B(?=(\d{3})+(?!\d))/g, " ") + " so'm"
}

// fayl: lib/format-price.test.ts
import { describe, expect, it } from "vitest"
import { formatPrice } from "./format-price"

describe("formatPrice", () => {
  it("minglarni bo'sh joy bilan ajratadi", () => {
    expect(formatPrice(25000)).toBe("25 000 so'm")
  })

  it("kichik sonni o'zgartirmaydi", () => {
    expect(formatPrice(900)).toBe("900 so'm")
  })

  it("kasr qismini yaxlitlaydi", () => {
    expect(formatPrice(1234567.6)).toBe("1 234 568 so'm")
  })
})

// fayl: lib/recipe-utils.ts
export function slugify(title: string) {
  return title.toLowerCase().replace(/'/g, "").trim().replace(/\s+/g, "-")
}

export function parseServings(value: string) {
  const n = Number(value)
  if (!Number.isInteger(n) || n < 1) throw new Error("Porsiya musbat butun son bo'lishi kerak")
  return n
}

export function toRecipe(title: string) {
  return { title, slug: slugify(title), tags: [] as string[] }
}

// fayl: lib/recipe-utils.test.ts
import { expect, test } from "vitest"
import { parseServings, slugify, toRecipe } from "./recipe-utils"

test("toBe — primitiv qiymat", () => {
  expect(slugify("Toshkent Oshi")).toBe("toshkent-oshi")
})

test("toEqual — obyekt tarkibi", () => {
  expect(toRecipe("Qo'y Manti")).toEqual({ title: "Qo'y Manti", slug: "qoy-manti", tags: [] })
  // toBe bu yerda o'tmaydi: har chaqiruv yangi obyekt
  expect(toRecipe("Osh")).not.toBe(toRecipe("Osh"))
})

test("toThrow — xato xabari", () => {
  expect(() => parseServings("0")).toThrow("musbat butun son")
  expect(parseServings("4")).toBe(4)
})

