"use client"

import { useState } from "react"

export function ServingsCounter({ initial = 2 }: { initial?: number }) {
  const [count, setCount] = useState(initial)
  return (
    <div>
      <p>Porsiya: {count}</p>
      <button onClick={() => setCount((c) => Math.max(1, c - 1))}>Kamaytirish</button>
      <button onClick={() => setCount((c) => c + 1)}>Oshirish</button>
    </div>
  )
}

