"use client"

import { useState } from "react"

export function SubscribeForm({ onSubscribe }: { onSubscribe: (email: string) => void }) {
  const [email, setEmail] = useState("")
  const valid = /^\S+@\S+\.\S+$/.test(email)
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault()
        onSubscribe(email)
      }}
    >
      <label htmlFor="email">Email</label>
      <input id="email" value={email} onChange={(e) => setEmail(e.target.value)} />
      <button type="submit" disabled={!valid}>Obuna bo'lish</button>
    </form>
  )
}

