// fayl: components/recipe-list.tsx
"use client"

import { useEffect, useState } from "react"

type Recipe = { id: number; name: string }

export function RecipeList() {
  const [recipes, setRecipes] = useState<Recipe[] | null>(null)
  const [failed, setFailed] = useState(false)

  useEffect(() => {
    fetch("/api/recipes")
      .then((res) => (res.ok ? res.json() : Promise.reject(new Error(String(res.status)))))
      .then(setRecipes)
      .catch(() => setFailed(true))
  }, [])

  if (failed) return <p role="alert">Retseptlarni yuklab bo'lmadi</p>
  if (!recipes) return <p>Yuklanmoqda...</p>
  return <ul>{recipes.map((r) => <li key={r.id}>{r.name}</li>)}</ul>
}

