"use client"

import { useEffect, useState } from "react"

type Props = { onSearch: (q: string) => void; delay?: number }

export function LiveSearch({ onSearch, delay = 300 }: Props) {
  const [q, setQ] = useState("")
  useEffect(() => {
    if (!q) return
    const id = setTimeout(() => onSearch(q), delay)
    return () => clearTimeout(id) // har harf yangi kutishni boshlaydi
  }, [q, delay, onSearch])
  return <input aria-label="Tezkor qidiruv" value={q} onChange={(e) => setQ(e.target.value)} />
}

