// fayl: components/cart.tsx
"use client"

import { createContext, useContext, useState, type ReactNode } from "react"

type Cart = { items: string[]; add: (name: string) => void }
const CartContext = createContext<Cart | null>(null)

export function CartProvider({ children, initial = [] }: { children: ReactNode; initial?: string[] }) {
  const [items, setItems] = useState(initial)
  const add = (name: string) => setItems((prev) => [...prev, name])
  return <CartContext value={{ items, add }}>{children}</CartContext>
}

function useCart() {
  const cart = useContext(CartContext)
  if (!cart) throw new Error("useCart CartProvider ichida ishlatilishi kerak")
  return cart
}

export function CartBadge() {
  return <span aria-label="Savat">{useCart().items.length}</span>
}

export function AddToCart({ name }: { name: string }) {
  const { add } = useCart()
  return <button onClick={() => add(name)}>Savatga: {name}</button>
}

