// fayl: hooks/use-favorites.ts
"use client"

import { useCallback, useState } from "react"

export function useFavorites(initial: string[] = []) {
  const [ids, setIds] = useState(initial)
  const toggle = useCallback((id: string) => {
    setIds((prev) => (prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]))
  }, [])
  return { ids, count: ids.length, toggle, has: (id: string) => ids.includes(id) }
}

// fayl: hooks/use-favorites.test.ts
import { expect, test } from "vitest"
import { act, renderHook } from "@testing-library/react"
import { useFavorites } from "./use-favorites"

test("toggle qo'shadi va olib tashlaydi", () => {
  const { result } = renderHook(() => useFavorites(["osh"]))
  expect(result.current.count).toBe(1)

  act(() => result.current.toggle("manti"))
  expect(result.current.ids).toEqual(["osh", "manti"])

  act(() => result.current.toggle("osh"))
  expect(result.current.has("osh")).toBe(false)
  expect(result.current.count).toBe(1)
})

test("rerender — useState boshlang'ich qiymatni qayta olmaydi", () => {
  const { result, rerender } = renderHook(({ initial }) => useFavorites(initial), {
    initialProps: { initial: ["somsa"] },
  })
  rerender({ initial: ["norin"] })
  expect(result.current.ids).toEqual(["somsa"])
})

