// fayl: app/weather/weather-widget.tsx
"use client"
import { useEffect, useState } from "react"

export function WeatherWidget() {
  const [data, setData] = useState<{ city: string; temp: number } | null>(null)
  useEffect(() => {
    fetch("/api/weather").then((r) => r.json()).then(setData)
  }, [])
  if (!data) return <p>Yuklanmoqda...</p>
  return <p>{data.city}: {data.temp}°C</p>
}

