import { test, expect } from "@playwright/test"

test("API 500 qaytarsa xato xabari", async ({ page }) => {
  await page.route("**/api/weather", (route) =>
    route.fulfill({ status: 500, json: { error: "Xizmat ishlamayapti" } })
