test("internet uzilsa, qayta urinish ishlaydi", async ({ page }) => {
  await page.route("**/api/weather", (route) => route.abort("internetdisconnected"))
  await page.goto("/weather")
  await expect(page.getByRole("alert")).toBeVisible()

  await page.unroute("**/api/weather")
  await page.route("**/api/weather", (route) => route.fulfill({ json: { city: "Buxoro", temp: 35 } }))
  await page.getByRole("button", { name: "Qayta urinish" }).click()
  await expect(page.getByText("Buxoro: 35°C")).toBeVisible()
})

// fayl: e2e/like.spec.ts
import { test, expect } from "@playwright/test"

test("Yoqdi tugmasi — Server Action ishlaydi", async ({ page }) => {
  await page.goto("/recipes/osh")
  const likeButton = page.getByRole("button", { name: "Yoqdi" })
  await expect(page.getByText("12 ta like")).toBeVisible()

  const actionResponse = page.waitForResponse(
    (res) => res.request().method() === "POST" && "next-action" in res.request().headers()
  )
  await likeButton.click()
  const res = await actionResponse

  expect(res.status()).toBe(200)
  await expect(likeButton).toHaveAttribute("aria-pressed", "true")
  await expect(page.getByText("13 ta like")).toBeVisible()
})

