"use client"
import { useEffect, useState } from "react"

export function Greeting() {
  const [text, setText] = useState("")
  useEffect(() => {
    const hour = new Date().getHours()
    setText(hour < 12 ? "Xayrli tong!" : hour < 18 ? "Xayrli kun!" : "Xayrli kech!")
  }, [])
  return <p>{text}</p>
}

