// fayl: cypress/e2e/weather.cy.ts
describe("Ob-havo vidjeti", () => {
  it("fixture ma'lumotini ko'rsatadi", () => {
    cy.intercept("GET", "/api/weather", { fixture: "weather.json" }).as("weather")
    cy.visit("/weather")
    cy.wait("@weather").its("response.statusCode").should("eq", 200)
    cy.contains("Samarqand: 28°C").should("be.visible")
  })

  it("server xatosida ogohlantirish", () => {
    cy.intercept("GET", "/api/weather", { statusCode: 500, body: { error: "xato" } }).as("fail")
    cy.visit("/weather")
    cy.wait("@fail")
    cy.get("[role=alert]").should("have.text", "Ob-havoni yuklab bo'lmadi")
  })
})

// fayl: cypress/support/commands.ts
declare global {
  namespace Cypress {
    interface Chainable {
      login(email: string, password: string): Chainable<void>
    }
  }
}

Cypress.Commands.add("login", (email: string, password: string) => {
  cy.session(
    [email],
    () => {
      cy.visit("/login")
      cy.get("input[name=email]").type(email)
      cy.get("input[name=password]").type(password, { log: false })
      cy.contains("button", "Kirish").click()
      cy.location("pathname").should("eq", "/dashboard")
    },
    { validate: () => cy.getCookie("session").should("exist") }
  )
})

export {}

