// fayl: app/components/counter.cy.tsx
import { Counter } from "./counter"

describe("<Counter />", () => {
  it("ikki marta bosilganda 2 ga oshadi", () => {
    cy.mount(<Counter initial={2} />)
    cy.contains("button", "+").click().click()
    cy.get("output").should("have.text", "4")
  })

  it("onChange chaqiriladi", () => {
    const onChange = cy.stub().as("onChange")
    cy.mount(<Counter initial={0} onChange={onChange} />)
    cy.contains("button", "+").click()
    cy.get("@onChange").should("have.been.calledWith", 1)
  })
})
